public partial class MainForm {
 Button RepairEntry(bool queued){var b=Btn("A/B · sửa câu",(s,e)=>OpenAudioRepair(queued));extraControls.Add(b);return b;}
 void AttachRepairRecording(RenderOptions o,List<Cue> input,KokoroEngine e,string path,string settings,string expectedHash){if(o.AiRepair!=null||o.TwoVoices||o.Prose||(!o.Locked&&!o.Anchored)||String.IsNullOrEmpty(path)||!File.Exists(path))return;if(StateFiles.Hash(path)!=expectedHash){e.ReportActivity("Nguồn đã đổi; chưa ghi nền A/B. Nhập lại SRT.");return;}var copy=VoiceRenderReport.Snapshot(input);var xml=XElement.Parse(settings);xml.SetAttributeValue("mode",o.Anchored?2:0);string saved=xml.ToString();e.Archive=e.Archive??new SpeechArchive(stateDir);o.RepairSnapshot=wav=>{try{if(StateFiles.Hash(path)!=expectedHash)throw new Exception("Nguồn thay đổi trong lúc tạo voice.");RepairSession.Capture(path,copy,stateDir,o.Anchored,saved,e,o,wav);}catch(Exception ex){e.ReportActivity("WAV vẫn được tạo; chưa lưu được dữ liệu sửa câu: "+ex.Message);}};}
 void OpenAudioRepair(bool queued){if(busy)return;try{if(queued){if(jobGrid.CurrentRow==null)throw new Exception("Chọn file SRT trong hàng đợi trước.");var j=jobs[jobGrid.CurrentRow.Index];if(j.State==JobState.ImportFailed)throw new Exception(j.Error);EditQueued();if(j.Timed&&(j.RepairMode==0||j.RepairMode==2))mode.SelectedIndex=j.RepairMode;else if(j.Timed&&batchMode.SelectedIndex==3)mode.SelectedIndex=2;}ReadGrid();if(TwoSpeakers||cues.Any(c=>SpeakerScript.Role(c)=="B"))throw new Exception("A/B · sửa câu dành cho kịch bản một giọng. Với kịch bản hai giọng, sửa Lời đọc / cột Giọng rồi tạo WAV mới.");if(proseInput||String.IsNullOrEmpty(sourcePath)||!File.Exists(sourcePath))throw new Exception("Mở một file SRT có timeline để so sánh A/B.");if(mode.SelectedIndex==1)throw new Exception("A/B giữ mốc nguồn: chọn Khóa SRT hoặc V15.6 trước.");int index=grid.CurrentRow==null?0:grid.CurrentRow.Index;var p=RepairSession.Open(sourcePath,cues,stateDir,mode.SelectedIndex==2);if(p.Settings.Length==0)p.Settings=CaptureSettings().Xml().ToString();if(player!=null)player.Stop();using(var d=new AudioRepairDialog(p,cues,index,catalog.All.ToList(),profile=>{var e=EngineFor(profile);e.DeviceMode=VoiceSettings.From(XElement.Parse(p.Settings)).Device;e.Archive=new SpeechArchive(stateDir);return e;},new LocalAi(root,VoiceSettings.From(XElement.Parse(p.Settings)).Device))){d.ShowDialog(this);if(d.Published){cues=VoiceRenderReport.Snapshot(d.PublishedWords);lastOutput=d.PublishedWav;lastAnchorReport=null;readingLive=false;waveform=new FileInfo(lastOutput).Length<=32*1024*1024?Wave.Read(lastOutput):null;wavePanel.Invalidate();openOutput.Enabled=File.Exists(lastOutput);lastVoiceReport=d.PublishedReport;if(editingJob!=null){editingJob.Cues=cues;editingJob.RepairMode=p.Anchored?2:0;editingJob.OutputPath=d.PublishedWav;editingJob.ReportPath=d.PublishedReport;editingJob.TimelineReport="Đã sửa A/B. Chi tiết: "+d.PublishedReport;editingJob.State=d.PublishedTranslationComplete?JobState.Done:JobState.TranslationIncomplete;editingJob.FailureCode=d.PublishedTranslationComplete?"":"TRANSLATION_INCOMPLETE";editingJob.Error="";editingJob.Warning=d.PublishedTranslationComplete?"Đã ghép audio A/B; xem báo cáo giọng từng chặng.":d.PublishedTranslationError;editingJob.AudioDuration=cues.Last().End;editingJob.DurationFinal=true;RefreshJobs();}Populate();SaveSession();status.Text=(d.PublishedTranslationComplete?"Đã ghép WAV/SRT/TXT: ":"TRANSLATION_INCOMPLETE · WAV đã kiểm tra; bộ chưa hoàn thiện: ")+p.Output;}else if(p.Report.Length>0)lastVoiceReport=p.Report;}}
 catch(Exception ex){Error(ex);}}
}
