  var editBox=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};editBox.RowStyles.Add(new RowStyle(SizeType.Absolute,25));editBox.RowStyles.Add(new RowStyle(SizeType.Percent,100));editBox.Controls.Add(new Label{Text="Sửa lời câu đang chọn (giữ mốc) · sau khi đổi lời, tạo thử lại trước khi áp dụng",Dock=DockStyle.Fill},0,0);editor=new TextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Vertical,MaxLength=2000};editBox.Controls.Add(editor,0,1);layout.Controls.Add(editBox,0,2);editor.TextChanged+=(s,e)=>{if(!loading){drafts[selected]=editor.Text;RefreshMetrics();}};
  toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,AutoScroll=true};layout.Controls.Add(toolbar,0,3);toolbar.Controls.Add(new Label{Text="Giọng A",AutoSize=true,Padding=new Padding(0,10,0,0)});voiceA=VoiceBox();toolbar.Controls.Add(voiceA);toolbar.Controls.Add(new Label{Text="Giọng B",AutoSize=true,Padding=new Padding(0,10,0,0)});voiceB=VoiceBox();toolbar.Controls.Add(voiceB);run=Button("Tạo thử A/B",async(s,e)=>await TrialBoth(),true);toolbar.Controls.Add(run);natural=new CheckBox{Text="Nghe tự nhiên",AutoSize=true,Padding=new Padding(0,9,0,0)};toolbar.Controls.Add(natural);natural.CheckedChanged+=(s,e)=>RefreshMetrics();
  var cards=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));cards.RowStyles.Add(new RowStyle(SizeType.Percent,100));cards.RowStyles.Add(new RowStyle(SizeType.Absolute,40));metricA=new Label{Dock=DockStyle.Fill,ForeColor=Color.Teal,AutoEllipsis=true};metricB=new Label{Dock=DockStyle.Fill,ForeColor=Color.FromArgb(65,70,170),AutoEllipsis=true};cards.Controls.Add(metricA,0,0);cards.Controls.Add(metricB,1,0);cards.Controls.Add(Button("▶ Nghe A",(s,e)=>PlayTake(true)),0,1);cards.Controls.Add(Button("▶ Nghe B",(s,e)=>PlayTake(false)),1,1);layout.Controls.Add(cards,0,4);
