 }
 Button Button(string text,EventHandler click,bool primary=false){var b=new Button{Text=text,AutoSize=true,MinimumSize=new Size(85,35),FlatStyle=FlatStyle.Flat,BackColor=primary?Color.Teal:Color.White,ForeColor=primary?Color.White:Color.FromArgb(20,39,64),Margin=new Padding(0,0,7,4),Padding=new Padding(5,0,5,0)};b.Click+=click;return b;}
 sealed class Item {public VoiceProfile Profile;public override string ToString(){return (Profile.Recommended?"★ ":"")+Profile.Name+" · "+Profile.MainStyle+" · "+Profile.Kind;}}
 ComboBox VoiceBox(){var c=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=225,DropDownWidth=650,IntegralHeight=false,DropDownHeight=360};foreach(var p in profiles)c.Items.Add(new Item{Profile=p});return c;}
 void SelectVoice(ComboBox box,string key){int i=box.Items.Cast<Item>().ToList().FindIndex(x=>x.Profile.Key==key);box.SelectedIndex=i<0?(box.Items.Count>0?0:-1):i;}
 VoiceProfile Profile(bool a){var item=(a?voiceA:voiceB).SelectedItem as Item;if(item==null)throw new Exception("Chọn giọng trước.");return item.Profile;}
 RepairPart Part{get{return project.At(selected);}}
 List<Cue> Words(){var all=project.Effective();int offset=project.Parts.TakeWhile(s=>s!=Part).Sum(s=>s.Stage.Cues.Count);var result=VoiceRenderReport.Snapshot(all.Skip(offset).Take(Part.Stage.Cues.Count));result[selected-offset].Text=editor.Text.Trim();return result;}
 bool Matches(RepairTake t,bool a){try{using(var e=factory(Profile(a)))return AudioRepair.Matches(t,e,AudioRepair.Options(project.Settings),Words());}catch{return false;}}
 void FillRows(){loading=true;try{rows.Rows.Clear();var all=project.Effective();for(int i=0;i<all.Count;i++){var c=all[i];var p=project.At(i);rows.Rows.Add(c.Id,Scripts.Stamp(c.Start)+" → "+Scripts.Stamp(c.End),c.Text,p.Selected!=null?p.Selected.Voice:File.Exists(p.Audio)?"Có WAV nền":"Chưa có WAV nền");}selected=Math.Max(0,Math.Min(selected,rows.Rows.Count-1));rows.CurrentCell=rows.Rows[selected].Cells[0];}finally{loading=false;}RefreshPart();}
 void RefreshPart(){if(player!=null)player.Stop();loading=true;try{editor.Text=drafts.ContainsKey(selected)?drafts[selected]:project.Effective()[selected].Text;}finally{loading=false;}var s=Part.Stage;scope.Text=Path.GetFileName(project.Source)+" · Câu "+(selected+1)+" · "+Scripts.Stamp(project.Sources[selected].Start)+" → "+Scripts.Stamp(project.Sources[selected].End)+"\r\n"+(s.Cues.Count>1?"V15.6: so sánh / tạo lại TOÀN CHẶNG cue "+s.Cues.First().Id+"–"+s.Cues.Last().Id:"Phạm vi: một câu")+" · khung "+Scripts.Stamp(s.Start)+" → "+Scripts.Stamp(s.End)+" · "+s.Budget.ToString("0.000")+"s · dùng thiết lập đã lưu.";RefreshMetrics();}
 void RefreshMetrics(){if(editor==null||rows==null||rows.Rows.Count==0)return;var s=Part;bool a=Matches(s.A,true),b=Matches(s.B,false);metricA.Text="A · "+(a?s.A.Describe(s.Stage.Start):"Chưa đo / lời hoặc giọng đã đổi. Bấm Tạo thử A/B.");metricB.Text="B · "+(b?s.B.Describe(s.Stage.Start):"Chưa đo / lời hoặc giọng đã đổi. Bấm Tạo thử A/B.");applyA.Enabled=!working&&a&&s.A.Success;applyB.Enabled=!working&&b&&s.B.Success;try{showA=a?Wave.Read(natural.Checked?s.A.NaturalAudio:s.A.Audio):null;showB=b?Wave.Read(natural.Checked?s.B.NaturalAudio:s.B.Audio):null;}catch{showA=showB=null;}waves.Invalidate();}
 void Navigate(int delta){int i=selected+delta;if(!working&&i>=0&&i<rows.Rows.Count)rows.CurrentCell=rows.Rows[i].Cells[0];}
 void Busy(bool value){working=value;rows.Enabled=editor.Enabled=toolbar.Enabled=!value;foreach(Control c in actions.Controls)c.Enabled=!value;stop.Enabled=value;UseWaitCursor=value;if(!value)RefreshMetrics();}
 async Task TrialBoth(){if(working)return;var part=Part;var words=Words();string settings=project.Settings;var failures=new List<string>();try{Busy(true);if(player!=null)player.Stop();foreach(bool a in new[]{true,false}){try{var profile=Profile(a);active=factory(profile);active.Archive=active.Archive??new SpeechArchive(Path.GetDirectoryName(project.Folder));active.Archive.Refresh=true;note.Text="Đang tạo thử "+(a?"A":"B")+" · "+profile.Name;var e=active;var o=AudioRepair.Options(settings);o.ReportContext=new VoiceReportContext{SourcePath=project.Source,SourceCues=project.Sources,VoiceKey=profile.Key,Purpose="Đo A/B "+(a?"A":"B")+" · chưa áp dụng"};await Task.Run(()=>AudioRepair.Trial(project,part,e,o,profile.Key,VoiceRenderReport.Snapshot(words),a?"A":"B"));}catch(OperationCanceledException){throw;}catch(Exception ex){failures.Add((a?"A":"B")+": "+ex.Message);note.Text=failures.Last();if(a)part.A=null;else part.B=null;project.Save();}finally{if(active!=null)active.Dispose();active=null;}}note.Text=failures.Count>0?String.Join(" · ",failures):"Đã đo A/B. Bản tràn vẫn nghe thử được. Khi ghép, chặng chưa có nền sẽ được tạo bằng giọng nền đã lưu.";}catch(OperationCanceledException){note.Text="Đã dừng. WAV đang dùng được giữ.";}catch(Exception ex){note.Text=ex.Message;}finally{Busy(false);if(closePending)Close();}}
 async Task Adopt(bool a){if(working)return;var changing=Part;var previous=changing.Selected;bool merged=false;try{var t=a?Part.A:Part.B;if(!Matches(t,a)||!t.Success)throw new Exception("Bản thử không còn khớp lời/giọng hoặc chưa đạt. Tạo thử lại.");Part.Selected=t;project.Save();Busy(true);if(player!=null)player.Stop();var saved=VoiceSettings.From(XElement.Parse(project.Settings));var profile=profiles.FirstOrDefault(v=>v.Key==saved.Key);if(profile==null)throw new Exception("Giọng nền không còn trong thư viện; cần tạo lại nền với giọng đã cài.");active=factory(profile);var engine=active;var o=AudioRepair.Options(project.Settings);o.ReportContext=new VoiceReportContext{SourcePath=project.Source,SourceCues=project.Sources,VoiceKey=profile.Key,Purpose="Ghép bản A/B đã chọn; giọng từng chặng ở cuối báo cáo"};o.Translator=translator;await Task.Run(()=>AudioRepair.Merge(project,engine,o,(n,m)=>{if(!IsDisposed)BeginInvoke((Action)(()=>note.Text=m));}));merged=true;Published=true;PublishedTranslationComplete=o.Translation!=null&&o.Translation.Complete;PublishedTranslationError=o.Translation==null?"Chưa có bộ dịch":o.Translation.Error;PublishedWav=project.Output;PublishedReport=project.Report;PublishedWords=VoiceRenderReport.Snapshot(project.PublishedCues);drafts.Clear();foreach(var c in project.Effective().Select((c,i)=>new{c,i}))drafts[c.i]=c.c.Text;FillRows();note.Text=(PublishedTranslationComplete?"Đã ghép WAV/SRT/TXT: ":"TRANSLATION_INCOMPLETE · WAV đạt; bộ chưa hoàn thiện: ")+project.Output+" · SRT nguồn giữ nguyên.";}catch(OperationCanceledException){note.Text="Đã dừng ghép. WAV cũ được giữ.";}catch(Exception ex){note.Text=ex.Message;}finally{if(!merged){changing.Selected=previous;project.Save();}if(active!=null)active.Dispose();active=null;Busy(false);if(closePending)Close();}}
 void SaveEditedSrt(){try{using(var d=new SaveFileDialog{Filter="SRT|*.srt",FileName=Path.GetFileNameWithoutExtension(project.Source)+".edited.srt",OverwritePrompt=true})if(d.ShowDialog()==DialogResult.OK){if(String.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(project.Source),StringComparison.OrdinalIgnoreCase))throw new Exception("Chọn tên khác để giữ SRT nguồn.");File.WriteAllText(d.FileName,Scripts.ToSrt(project.PublishedCues.Count>0?project.PublishedCues:project.Effective()),new UTF8Encoding(false));note.Text="Đã lưu SRT bản sửa: "+d.FileName;}}catch(Exception ex){note.Text=ex.Message;}}
 void PlayTake(bool a){try{var t=a?Part.A:Part.B;if(!Matches(t,a))throw new Exception("Tạo thử lại sau khi đổi lời / giọng.");if(player!=null){player.Stop();player.Dispose();}player=new SoundPlayer(natural.Checked?t.NaturalAudio:t.Audio);player.Load();player.Play();note.Text="Nghe "+(a?"A":"B")+(natural.Checked?" · tự nhiên (trước căn)":" · đã căn khung, trước cân âm tổng");}catch(Exception ex){note.Text=ex.Message;}}
 void Draw(Graphics g){if(rows.Rows.Count==0)return;double range=Math.Max(Part.Stage.Budget,Math.Max(showA==null?0:showA.Duration,showB==null?0:showB.Duration));int left=38,width=Math.Max(1,waves.Width-62);g.DrawString(Scripts.Stamp(Part.Stage.Start),Font,Brushes.SlateGray,left,0);g.DrawString(natural.Checked?"Audio tự nhiên · trước căn":"Audio đã căn · vùng nhạt là nghỉ cuối",Font,Brushes.SlateGray,Math.Max(180,waves.Width/2-140),0);int boundary=left+(int)(width*Part.Stage.Budget/range);g.DrawString(Scripts.Stamp(Part.Stage.End),Font,Brushes.Crimson,Math.Min(waves.Width-100,boundary-45),0);foreach(bool a in new[]{true,false}){var w=a?showA:showB;int mid=a?43:77;g.DrawString(a?"A":"B",Font,a?Brushes.Teal:Brushes.Indigo,8,mid-10);if(w==null)continue;var pen=a?Pens.Teal:Pens.Indigo;var take=a?Part.A:Part.B;if(!natural.Checked&&take!=null&&take.Tail>.03){int endSpeech=left+(int)(width*take.SpeechSeconds/range);using(var bg=new SolidBrush(Color.FromArgb(234,238,245)))g.FillRectangle(bg,endSpeech,mid-16,Math.Max(0,boundary-endSpeech),32);if(boundary-endSpeech>95)g.DrawString("Nghỉ "+take.Tail.ToString("0.00")+"s",new Font(Font.FontFamily,8),Brushes.SlateGray,endSpeech+3,mid-9);}for(int x=0;x<width;x++){int start=(int)(x/(double)width*range*24000);if(start>=w.Samples.Length)break;int end=Math.Min(w.Samples.Length,(int)((x+1)/(double)width*range*24000));int peak=0;for(int j=start;j<end;j+=Math.Max(1,(end-start)/8))peak=Math.Max(peak,Math.Abs((int)w.Samples[j]));float h=peak/32768f*15;g.DrawLine(pen,left+x,mid-h,left+x,mid+h);}}g.DrawLine(Pens.Crimson,boundary,22,boundary,waves.Height);}
}
